// A readable summary of a rule set for the review screen (Hungarian or English), generated by code
// so it always says what the engine will compute (the extraction never writes UI text). Pure.

import { getMessages, type Locale } from "@/lib/i18n";
import { describeFormula } from "./expr";
import type { Gate, PostStep, RuleComponent, SubjectRules } from "./types";

export interface RulesSection {
  title: string;
  lines: string[];
}

const text = (locale: Locale) => getMessages(locale).rules.describe;

function componentLine(c: RuleComponent, locale: Locale): string {
  const t = text(locale);
  switch (c.kind) {
    case "attendance":
      return c.limit
        ? t.attendanceLimit(c.label, c.limit.maxAbsences, c.limit.countExcused, t.gateFail[c.limit.onExceed])
        : t.attendanceRecord(c.label);
    case "exam": {
      if (c.scale.kind === "grade") return t.examGrade(c.label, c.scale.passAt);
      const parts = c.scale.parts?.length ? t.examParts(c.scale.parts.map((p) => t.examPart(p.label, p.max, p.passAt)).join(", ")) : "";
      return t.examPoints(c.label, c.scale.max, c.scale.passAt, parts);
    }
    case "assignment":
      return t.assignment(c.label, c.outcomes.map((o) => t.assignmentOutcome(o.label, o.points)).join(", "));
    case "series": {
      const s = c.scoring;
      if (s.kind === "plusMinus") return t.seriesPlusMinus(c.label, c.count);
      if (s.kind === "percent") return t.seriesPercent(c.label, c.count, s.passAt, s.attempts, !!s.onTimeOnly);
      const parts = s.parts?.length ? t.seriesParts(s.parts.map((p) => t.seriesPart(p.label, p.max)).join(" + ")) : "";
      return t.seriesPoints(c.label, c.count, s.max, parts);
    }
    case "bonus":
      return t.bonus(c.label, c.cap);
  }
}

/** A readable name for every id a formula can use (components, parts, retakes, derived values, tables, outcomes). */
export function ruleLabels(rules: SubjectRules, locale: Locale = "hu"): Record<string, string> {
  const t = text(locale);
  const labels: Record<string, string> = {};
  for (const c of rules.components) {
    labels[c.id] = c.label;
    const parts = c.kind === "exam" && c.scale.kind === "points" ? c.scale.parts : c.kind === "series" && c.scoring.kind === "points" ? c.scoring.parts : undefined;
    for (const p of parts ?? []) labels[`${c.id}.${p.id}`] = t.partOf(c.label, p.label);
  }
  for (const r of rules.retakes) labels[r.id] = r.label;
  for (const d of rules.derived) labels[d.id] = d.label;
  for (const tb of rules.tables) {
    const owner = rules.components.find((c) => tb.id === `${c.id}tabla` || tb.id.startsWith(c.id));
    labels[tb.id] = tb.id === "jegy" ? t.jegyTable : owner ? t.tableOf(owner.label) : t.tableUnknown(tb.id);
  }
  for (const o of rules.outcomes) labels[o.id] = t.outcomeShort(o.label);
  return labels;
}

/** A formula in words, with the rule set's names. */
export function formulaDescriber(rules: SubjectRules, locale: Locale = "hu"): (src: string) => string {
  const labels = ruleLabels(rules, locale);
  return (src) => describeFormula(src, labels, locale);
}

/** A table's name as a title ("Jegytáblázat", "Elméleti zh táblázata"). */
export function tableTitle(rules: SubjectRules, tableId: string, locale: Locale = "hu"): string {
  const name = text(locale).stripArticle(ruleLabels(rules, locale)[tableId] ?? tableId);
  return `${name.charAt(0).toUpperCase()}${name.slice(1)}`;
}

/** "nincs jegy" / "elégtelen" for a gate's `onFail`, in the given language. */
export function gateFailText(locale: Locale = "hu"): Record<Gate["onFail"], string> {
  return text(locale).gateFail;
}
/** How a retake slot picks the result it replaces, in the given language. */
export function retakePickText(locale: Locale = "hu"): Record<string, string> {
  return text(locale).retakePick;
}
/** The Hungarian texts, for callers that have not been given a language yet. */
export const GATE_FAIL_TEXT = gateFailText("hu");
export const RETAKE_PICK_TEXT = retakePickText("hu");

/** A post step ("legfeljebb 4", "−1 jegy, ha …"). */
export function postStepText(p: PostStep, f: (src: string) => string, locale: Locale = "hu"): string {
  const t = text(locale);
  return p.kind === "cap" ? t.postCap(p.max) : t.postAdd(p.delta, f(p.when));
}

export function describeRules(rules: SubjectRules, locale: Locale = "hu"): RulesSection[] {
  const t = text(locale);
  const labels = ruleLabels(rules, locale);
  const f = formulaDescriber(rules, locale);
  const post = (p: PostStep) => postStepText(p, f, locale);

  const sections: RulesSection[] = [{ title: t.sections.components, lines: rules.components.map((c) => componentLine(c, locale)) }];
  if (rules.retakes.length) {
    sections.push({
      title: t.sections.retakes,
      lines: rules.retakes.map((r) =>
        t.retake(r.label, r.targets.map((x) => labels[x] ?? x).join(", "), t.retakePick[r.pick], r.mode === "replace", r.eligible ? f(r.eligible) : undefined)
      ),
    });
  }
  const calc = [
    ...rules.derived.map((d) => `${d.label}: ${f(d.expr)}`),
    ...rules.tables.map((tb) => `${tableTitle(rules, tb.id, locale)}: ${tb.rows.map((row) => t.tableRow(row.min, row.value)).join(", ")}`),
  ];
  if (calc.length) sections.push({ title: t.sections.calc, lines: calc });
  for (const o of rules.outcomes) {
    const lines: string[] = [];
    for (const g of o.gates ?? []) lines.push(t.gateLine(t.gate(g.label, t.gateFail[g.onFail])));
    for (const p of o.paths) {
      const head = o.paths.length > 1 ? t.pathHead(p.label, p.when ? f(p.when) : undefined) : "";
      const gates = (p.gates ?? []).map((g) => t.gate(g.label, t.gateFail[g.onFail]));
      lines.push(t.pathLine(head, gates.join("; "), f(p.grade), p.post?.length ? p.post.map(post).join("; ") : ""));
    }
    if (o.paths.length > 1) lines.push(o.select === "best" ? t.bestPath : t.firstPath);
    sections.push({ title: o.label, lines });
  }
  return sections;
}
